import {createGunzip} from 'node:zlib';
import {extractAttachment} from '../vendor/pdf-library.mjs';

try {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  const input = Buffer.concat(chunks);
  if (input.subarray(0, 7).toString() !== 'SHOPPDF') throw new Error('bad envelope');
  // Check the expanded size before calling the unbounded vendor API.
  const gunzip = createGunzip();
  gunzip.end(input.subarray(7));
  let size = 0;
  for await (const chunk of gunzip) {
    size += chunk.length;
    if (size > 1024 * 1024) throw new Error('attachment too large');
  }
  const xml = await extractAttachment(input);
  if (process.resourceUsage().maxRSS > 96 * 1024) throw new Error('parser memory limit exceeded');
  const title = /<title>(.*?)<\/title>/s.exec(xml)?.[1];
  if (!title) throw new Error('no title');
  process.stdout.write(JSON.stringify({title}));
} catch {
  process.exitCode = 1;
}

