import {spawn} from 'node:child_process';

const MAX_INPUT = 64 * 1024;
const TIMEOUT = 200;
let active = false;
const queue = [];
const unreadable = () => ({status: 422, body: {kind: 'unreadable', kept: true}});

function parse(buffer) {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [new URL('./parser.mjs', import.meta.url).pathname], {stdio: ['pipe', 'pipe', 'ignore']});
    let output = '';
    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (child.exitCode === null && child.pid) {
        child.once('close', () => resolve(result));
        child.kill('SIGKILL');
      } else resolve(result);
    };
    const timer = setTimeout(() => finish(unreadable()), TIMEOUT);
    child.on('error', () => finish(unreadable()));
    child.stdin.on('error', () => {});
    child.stdout.on('data', chunk => {
      output += chunk;
      if (output.length > 1024 * 1024 + 1024) finish(unreadable());
    });
    child.on('close', code => {
      if (code !== 0) return finish(unreadable());
      try {
        const {title} = JSON.parse(output);
        if (typeof title !== 'string' || !title) return finish(unreadable());
        finish({status: 200, body: {kind: 'proposal', title}});
      } catch { finish(unreadable()); }
    });
    child.stdin.end(buffer);
  });
}

function run(buffer) {
  active = true;
  return parse(buffer).finally(() => {
    const next = queue.shift();
    if (next) run(next.buffer).then(next.resolve);
    else active = false;
  });
}

export function upload(buffer) {
  if (buffer.length > MAX_INPUT) return Promise.resolve(unreadable());
  if (!active) return run(buffer);
  if (queue.length >= 2) return Promise.resolve({status: 503, body: {kind: 'busy'}});
  return new Promise(resolve => queue.push({buffer, resolve}));
}

